package com.joaogabrielbmf.gestao_vendas.service; import org.springframework.stereotype.Service; import java.util.*; @Service public class TextoService{private static final Set<String> M=Set.of("de","da","do","das","dos","e"); public String titulo(String v){if(v==null)return null;String[] ps=v.trim().toLowerCase(Locale.forLanguageTag("pt-BR")).replaceAll("\\s+"," ").split(" ");StringBuilder r=new StringBuilder();for(int i=0;i<ps.length;i++){String x=ps[i];if(x.isBlank())continue;String y=(i>0&&M.contains(x))?x:Character.toUpperCase(x.charAt(0))+x.substring(1);if(r.length()>0)r.append(' ');r.append(y);}return r.toString();} public String upper(String v){return v==null?null:v.trim().replaceAll("\\s+"," ").toUpperCase(Locale.ROOT);} public String email(String v){return v==null?null:v.trim().toLowerCase(Locale.ROOT);}}